package cn.adc.shared.security;
import cn.adc.shared.config.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class StaffBindingAdapterTest {
 @Test void subjectChangeWithinOneRequestInvalidatesIdentityAndCsrf(){var current=new AtomicReference<>(new StaffSessionIdentityAdapter.VerifiedSession("synthetic-a","token-a",stamp(true)));var identity=new StaffSessionIdentityAdapter(current::get);assertEquals("synthetic-a",identity.current().orElseThrow());current.set(new StaffSessionIdentityAdapter.VerifiedSession("synthetic-b","token-b",stamp(true)));assertTrue(identity.current().isEmpty());assertThrows(SecurityException.class,()->identity.requireCsrf("token-b"));}
 static SourceStamp stamp(boolean usable){return new SourceStamp("SYNTHETIC-authority","v1","test-reviewer",Instant.parse("2026-11-05T00:00:00Z"),usable);}
 @Test void verifiedSessionIsRequiredAndCsrfBoundToServerSession(){var session=new AtomicReference<StaffSessionIdentityAdapter.VerifiedSession>();var a=new StaffSessionIdentityAdapter(session::get);assertTrue(a.current().isEmpty());session.set(new StaffSessionIdentityAdapter.VerifiedSession("synthetic-hq","synthetic-csrf",stamp(true)));assertEquals("synthetic-hq",a.current().orElseThrow());a.requireCsrf("synthetic-csrf");assertThrows(SecurityException.class,()->a.requireCsrf("header-cannot-authenticate"));session.set(new StaffSessionIdentityAdapter.VerifiedSession("synthetic-hq","synthetic-csrf",stamp(false)));assertTrue(a.current().isEmpty());}
 @Test void bindingsAreReloadedAndNeverGrantPublishFromEditOrRoleAlone(){var g=new StaffAuthorization.Grant("v1",Set.of("HQ"),Set.of("DURATION_EDIT"),Set.of(),true);var entries=new AtomicReference<>(List.of(new StaffBindingAdapter.Entry("synthetic-hq",g,stamp(true))));var adapter=new StaffBindingAdapter(entries::get);var auth=new StaffAuthorization(()->Optional.of("synthetic-hq"),adapter::bindings);auth.require("DURATION_EDIT",Set.of());assertThrows(SecurityException.class,()->auth.require("DURATION_PUBLISH",Set.of()));entries.set(List.of());assertThrows(SecurityException.class,()->auth.require("DURATION_EDIT",Set.of()));}
 @Test void duplicateActorUnknownActionOrUnavailableAuthorityDeny(){var g=new StaffAuthorization.Grant("v1",Set.of("HQ"),Set.of("DURATION_EDIT"),Set.of(),true);var e=new StaffBindingAdapter.Entry("synthetic-hq",g,stamp(true));assertTrue(new StaffBindingAdapter(()->List.of(e,e)).bindings().isEmpty());assertTrue(new StaffBindingAdapter(()->{throw new IllegalStateException();}).bindings().isEmpty());assertTrue(new StaffBindingAdapter(()->List.of(new StaffBindingAdapter.Entry("synthetic-hq",new StaffAuthorization.Grant("v1",Set.of("HQ"),Set.of("ALL"),Set.of(),true),stamp(true)))).bindings().isEmpty());}
}
